<?php
namespace Upyun; class Config { public $bucketName; public $operatorName; public $operatorPassword; public $useSsl; public $uploadType = 'AUTO'; public $sizeBoundary = 31457280; public $timeout = 60; public $processNotifyUrl; public $debug = false; private $version = '3.0.0'; private $formApiKey; public static $restApiEndPoint; const ED_AUTO = 'v0.api.upyun.com'; const ED_TELECOM = 'v1.api.upyun.com'; const ED_CNC = 'v2.api.upyun.com'; const ED_CTT = 'v3.api.upyun.com'; const ED_VIDEO = 'p0.api.upyun.com'; const ED_PURGE = 'http://purge.upyun.com/purge/'; public function __construct($bucketName, $operatorName, $operatorPassword) { $this->bucketName = $bucketName; $this->operatorName = $operatorName; $this->setOperatorPassword($operatorPassword); $this->useSsl = false; self::$restApiEndPoint = self::ED_AUTO; } public function setOperatorPassword($operatorPassword) { $this->operatorPassword = md5($operatorPassword); } public function getFormApiKey() { if (! $this->formApiKey) { throw new \Exception('form api key is empty.'); } return $this->formApiKey; } public function setFormApiKey($key) { $this->formApiKey = $key; } public function getVersion() { return $this->version; } public function getPretreatEndPoint() { return $this->getProtocol() . self::ED_VIDEO; } public function getProtocol() { return $this->useSsl ? 'https://' : 'http://'; } } 